//! 🧪️ Canonical paged receiving agrees with Python hashlib and retains exact original controls and backing at every refusal.
use super::*;
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_framework_value::retirement::controlled::ControlledRetirement;
use crate::retained::tests::{outcome,turn,warm};
/// 🧯️ Closes one paged bytes receiver turn under a real original action.
fn close_step(receiver:&mut RetainedWireBytesDecode,grant:RetainedCloneGrant)->Result<RetainedWireFieldStep,semio_framework_value::OriginalRetirementFailure>{turn(grant,|effect|receiver.close_step(effect))}
/// 🧯️ Closes one controlled retirement turn under a real original action granted its quoted work.
fn retire_step(close:&mut ControlledRetirement<Bytes>,grant:RetainedCloneGrant)->semio_framework_value::RetainedCloneStep{let work=close.next_computational_work(4096).unwrap();outcome(grant,work,|effect|match close.step(4096,effect){semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn,semio_framework_value::RetainedWorkPoll::Pending{work}=>semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default())),work}}).result.unwrap()}
fn observe<T>(operation:impl FnOnce()->T)->(T,(usize,usize)){let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(operation);(result,(born,released))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096&&d.release_bytes<=4096,"original frontier exceeds its physical bound: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn denials(g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut denied=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g}];if g.maximum_copy_bytes>0{denied.push(RetainedCloneGrant{maximum_copy_bytes:0,..g})}if g.maximum_capacity_bytes>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:g.maximum_capacity_bytes-1,..g})}if g.maximum_release_bytes>0{denied.push(RetainedCloneGrant{maximum_release_bytes:g.maximum_release_bytes-1,..g})}denied}
struct Original<'a>{bytes:&'a[u8],authority:(u64,u64)}
impl RetainedWireByteSource for Original<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{range_start:0,address:self.bytes.as_ptr()as usize,extent:self.bytes.len(),authority:Some(self.authority)}}fn byte_at(&self,index:usize)->Option<u8>{self.bytes.get(index).copied()}}
#[test]
fn original_binary_field_pages_preserve_actual_issuer_denials_cancellation_and_physical_receipts(){ warm();
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let seed=law["seed"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>();let payload=seed.repeat(law["repeats"].as_u64().unwrap()as usize);let mut wire=vec![0x53,0x50,0x52];wire.extend_from_slice(&payload);wire.extend_from_slice(&[7,11]);let source=Original{bytes:&wire,authority:(271,13)};let foreign=Original{bytes:&wire,authority:(271,17)};let original_pointer=wire.as_ptr();
 for body in law["bodyBytes"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for cancellation in law["cancelTurns"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain(std::iter::once(None)){
  let(mut receiver,heap)=observe(||RetainedWireBytesDecode::new_range(&source,(3,3+payload.len())).unwrap());assert_eq!(heap,(0,0));let mut allow=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut allow);let(mut born,mut released)=(0,0);let mut turns=0;
  while !receiver.is_ready()&&cancellation!=Some(turns){let d=receiver.demands(&source,body).unwrap();let g=grant(d);let(result,heap)=observe(||receiver.advance(&foreign,g));assert!(result.is_err());assert_eq!(heap,(0,0));assert!(receiver.take_receipt().is_none());for denied in denials(g){let(result,heap)=observe(||receiver.advance(&source,denied).unwrap());assert_eq!(result,RetainedWireFieldStep::Blocked);assert_eq!(heap,(0,0));assert!(receiver.take_receipt().is_none());assert_eq!(receiver.demands(&source,body).unwrap(),d);}native.charge(d.capacity_bytes).unwrap();let(result,heap)=observe(||receiver.advance(&source,g).unwrap());assert_ne!(result,RetainedWireFieldStep::Blocked);let(issued,p)=receiver.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;released+=heap.1;turns+=1;assert!(turns<20000);}
  if cancellation.is_none(){assert!(receiver.is_ready());let pointer=receiver.output.as_ref().unwrap().retained_bytes().contiguous_at(0).unwrap().as_ptr();let d=receiver.demands(&source,body).unwrap();let g=grant(d);let mut occupied=Some(Bytes::default());let(result,heap)=observe(||receiver.take_into(&mut occupied,g).unwrap());assert_eq!(result,RetainedWireFieldStep::Blocked);assert_eq!(heap,(0,0));let mut output=None;for denied in denials(g){assert_eq!(receiver.take_into(&mut output,denied).unwrap(),RetainedWireFieldStep::Blocked);assert!(output.is_none());}let(_,heap)=observe(||receiver.take_into(&mut output,g).unwrap());let(issued,p)=receiver.take_receipt().unwrap();assert_eq!(issued,g);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(receiver.terminal_is_empty());let output=output.unwrap();assert_eq!(output.original_source_identity().range_start,0);assert_eq!(output.retained_bytes().contiguous_at(0).unwrap().as_ptr(),pointer);assert_eq!(output.iter().collect::<Vec<_>>(),payload);let mut hash=semio_framework_hash::Sha256::new();for part in output.retained_bytes().iter(){hash.update(&[*part]);}let digest=hash.finalize().iter().map(|byte|format!("{byte:02x}")).collect::<String>();assert_eq!(digest,law["sha256"].as_str().unwrap());let mut close=ControlledRetirement::new(output).map_err(|(error,_)|error).unwrap();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();let g=grant(d);native.charge(d.capacity_bytes).unwrap();let(step,heap)=observe(||retire_step(&mut close,g));let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;released+=heap.1;}}
  else{receiver.cancel();for _ in 0..20000{if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();let g=grant(d);for denied in denials(g){let(result,heap)=observe(||close_step(&mut receiver,denied).unwrap());assert_eq!(result,RetainedWireFieldStep::Blocked);assert_eq!(heap,(0,0));assert!(receiver.take_receipt().is_none());assert_eq!(receiver.close_demands(4096).unwrap(),d);}native.charge(d.capacity_bytes).unwrap();let(_,heap)=observe(||close_step(&mut receiver,g).unwrap());let(issued,p)=receiver.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;released+=heap.1;}assert!(receiver.terminal_is_empty());}
  assert_eq!(born,released);assert_eq!(native.owned_bytes(),born);assert_eq!(wire.as_ptr(),original_pointer);assert_eq!(source.bytes,&wire);
 }}
}
